<script>
(()=>{
  const form=document.querySelector('[data-review-form]');if(!form)return;
  const list=document.querySelector('[data-review-list]'),feedback=form.querySelector('[data-review-feedback]'),summary=document.querySelector('[data-review-summary]'),tab=document.querySelector('#product-tab-reviews span'),pagination=document.querySelector('[data-review-pagination]'),pageStatus=pagination.querySelector('[data-review-page-status]'),pageButtons=[...pagination.querySelectorAll('[data-review-page-step]')];
  let currentPage=Number(list.dataset.page||1),pageCount=1,requestId=0;
  const dateLabel=value=>{const date=new Date(String(value).replace(' ','T'));return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('bg-BG').format(date)};
  function showMessage(message,error=false){feedback.textContent=message;feedback.classList.toggle('is-error',error);feedback.hidden=false}
  function renderReview(review){
    const item=document.createElement('article'),head=document.createElement('div'),authorBox=document.createElement('div'),author=document.createElement('p'),stars=document.createElement('div'),time=document.createElement('time'),description=document.createElement('p'),emptyStars=document.createElement('span');
    item.className='review-item';head.className='review-item-head';author.className='review-author';author.textContent=review.author_name;stars.className='review-stars';stars.setAttribute('role','img');stars.setAttribute('aria-label','Оценка: '+review.rating+' от 5 звезди');stars.append(document.createTextNode('★'.repeat(Number(review.rating))));emptyStars.textContent='★'.repeat(5-Number(review.rating));stars.append(emptyStars);authorBox.append(author,stars);time.dateTime=String(review.created_at).replace(' ','T');time.textContent=dateLabel(review.created_at);head.append(authorBox,time);description.className='review-description';description.textContent=review.description;item.append(head,description);return item;
  }
  function updateSummary(data){const count=Number(data.count),average=Number(data.average);summary.textContent=count?'Средна оценка '+average.toFixed(1).replace('.',',')+' от 5 · '+count+' '+(count===1?'отзив':'отзива'):'Все още няма публикувани отзиви за този продукт.';tab.textContent='Отзиви ('+count+')';}
  function updatePagination(data){currentPage=Number(data.page)||1;pageCount=Number(data.pages)||1;pageStatus.textContent='Страница '+currentPage+' от '+pageCount;pagination.hidden=pageCount<=1;pageButtons.forEach(button=>{const step=Number(button.dataset.reviewPageStep);button.disabled=step<0?currentPage<=1:currentPage>=pageCount})}
  async function loadPage(page,showError=true,scrollToHeading=false){
    const id=++requestId;list.classList.add('is-loading');pageButtons.forEach(button=>button.disabled=true);
    try{const response=await fetch(form.action+'?page='+encodeURIComponent(page),{credentials:'same-origin',headers:{Accept:'application/json'}}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Отзивите не можаха да бъдат заредени.');if(id!==requestId)return false;const data=payload.data;list.replaceChildren(...data.items.map(renderReview));list.dataset.page=String(data.page);updateSummary(data);updatePagination(data);if(scrollToHeading)document.querySelector('[data-review-heading]')?.scrollIntoView({behavior:'smooth',block:'start'});return true;}
    catch(error){if(showError)showMessage(error instanceof Error?error.message:'Отзивите не можаха да бъдат заредени.',true);return false;}
    finally{if(id===requestId){list.classList.remove('is-loading');updatePagination({page:currentPage,pages:pageCount})}}
  }
  pagination.addEventListener('click',event=>{const button=event.target.closest('[data-review-page-step]');if(!button||button.disabled)return;loadPage(currentPage+Number(button.dataset.reviewPageStep),true,true);});
  form.addEventListener('submit',async event=>{
    event.preventDefault();if(form.dataset.pending==='1')return;form.dataset.pending='1';const submit=form.querySelector('[type=submit]');submit.disabled=true;feedback.hidden=true;feedback.classList.remove('is-error');
    try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{Accept:'application/json'}}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Отзивът не можа да бъде публикуван.');form.reset();const loaded=await loadPage(1,true,true);if(!loaded)throw new Error('Отзивът е публикуван, но списъкът не можа да се обнови. Обновете страницата.');showMessage(payload.data.message);}
    catch(error){showMessage(error instanceof Error?error.message:'Възникна грешка. Опитайте отново.',true);}
    finally{delete form.dataset.pending;submit.disabled=false;}
  });
  loadPage(currentPage,false);
})();
</script>
<script>
(()=>{
  const root=document.querySelector('[data-product-tabs]');if(!root)return;
  const tabs=[...root.querySelectorAll('[role=tab]')],panels=tabs.map(tab=>document.getElementById(tab.getAttribute('aria-controls')));
  function tabKey(tab){return tab.getAttribute('aria-controls').replace('product-panel-','')}
  function scrollToReviews(){document.querySelector('[data-review-heading]')?.scrollIntoView({behavior:'smooth',block:'start'})}
  function activate(index,{focus=false,updateUrl=false,scroll=false}={}){
    const next=(index+tabs.length)%tabs.length;
    tabs.forEach((tab,i)=>{const selected=i===next;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;panels[i].hidden=!selected;panels[i].classList.remove('is-entering')});
    if(focus)tabs[next].focus();
    if(updateUrl){const url=new URL(location.href);url.hash=tabKey(tabs[next]);history.pushState({},'',url.pathname+url.search+url.hash)}
    requestAnimationFrame(()=>{panels[next].classList.add('is-entering');if(scroll&&tabKey(tabs[next])==='reviews')scrollToReviews()});
  }
  function syncFromUrl(){const key=location.hash.slice(1),index=tabs.findIndex(tab=>tabKey(tab)===key);if(index>=0)activate(index,{scroll:key==='reviews'})}
  tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activate(index,{updateUrl:true,scroll:tabKey(tab)==='reviews'}));tab.addEventListener('keydown',event=>{let next=index;if(event.key==='ArrowRight')next=index+1;else if(event.key==='ArrowLeft')next=index-1;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();activate(next,{focus:true,updateUrl:true,scroll:tabKey(tabs[next])==='reviews'})})});
  window.addEventListener('popstate',syncFromUrl);window.addEventListener('hashchange',syncFromUrl);
  const key=location.hash.slice(1),initial=tabs.findIndex(tab=>tabKey(tab)===key);activate(initial>=0?initial:0,{scroll:key==='reviews'});
})();
</script>
<script>
(()=>{
  const gallery=document.querySelector('[data-product-gallery]');if(!gallery)return;
  const stage=gallery.querySelector('[data-gallery-open]'),main=gallery.querySelector('[data-variant-image-gallery]'),thumbs=[...gallery.querySelectorAll('[data-gallery-select]')],lightbox=gallery.querySelector('[data-gallery-lightbox]');
  if(!stage||!main||!lightbox)return;
  const lightboxImage=lightbox.querySelector('[data-gallery-lightbox-image]'),caption=lightbox.querySelector('[data-gallery-caption]'),count=lightbox.querySelector('[data-gallery-count]'),closeButton=lightbox.querySelector('[data-gallery-close]'),previous=lightbox.querySelector('[data-gallery-previous]'),next=lightbox.querySelector('[data-gallery-next]');
  let index=0,returnFocus=null,previousOverflow='',closeTimer=0,touchStartX=null;
  const slideStates=new WeakMap();function swapImage(target,src,alt,direction=1){if(!target||!src)return;const resolved=new URL(src,document.baseURI).href;if(target.src===resolved){target.alt=alt||'';return}const show=()=>{const old=slideStates.get(target);if(old){window.clearTimeout(old.timer);target.src=old.src;target.alt=old.alt;old.incoming.remove();target.classList.remove('gallery-slide-out');slideStates.delete(target)}const frame=target.closest('[data-gallery-image-viewport]')||target.parentElement,incoming=document.createElement('img');incoming.className='gallery-slide-in';incoming.src=src;incoming.alt=alt||'';incoming.style.objectFit=getComputedStyle(target).objectFit;incoming.style.transform=`translateX(${direction<0?'-100%':'100%'})`;frame.append(incoming);target.classList.remove('gallery-slide-out');void incoming.offsetWidth;const state={src,alt:alt||'',incoming,timer:0};slideStates.set(target,state);requestAnimationFrame(()=>{requestAnimationFrame(()=>{if(slideStates.get(target)!==state)return;target.classList.add('gallery-slide-out');incoming.style.transform='translateX(0)'})});const finish=()=>{if(slideStates.get(target)!==state)return;target.src=state.src;target.alt=state.alt;target.classList.remove('gallery-slide-out');target.style.transform='';incoming.remove();slideStates.delete(target)};incoming.addEventListener('transitionend',event=>{if(event.propertyName==='transform')finish()},{once:true});state.timer=window.setTimeout(finish,480)};const preload=new Image();preload.onload=show;preload.onerror=show;preload.src=src}
  const sources=thumbs.map(button=>({src:button.dataset.gallerySrc,alt:button.dataset.galleryAlt||''}));
  function reflect(src,alt,direction=1){swapImage(main,src,alt,direction);const match=thumbs.findIndex(button=>button.dataset.gallerySrc===src);thumbs.forEach((button,i)=>{const active=i===match;button.setAttribute('aria-pressed',String(active));button.classList.toggle('is-active',active)});if(match>=0)index=match}
  function select(nextIndex){if(!sources.length)return;const direction=nextIndex>=index?1:-1;index=(nextIndex+sources.length)%sources.length;const image=sources[index];reflect(image.src,image.alt,direction);if(lightboxImage)swapImage(lightboxImage,image.src,image.alt,direction);if(caption)caption.textContent=image.alt;if(count)count.textContent=`${index+1} / ${sources.length}`;thumbs[index]?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})}
  function open(){returnFocus=document.activeElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';lightbox.hidden=false;lightbox.setAttribute('aria-hidden','false');lightboxImage.src=main.src;lightboxImage.alt=main.alt;if(caption)caption.textContent=main.alt;if(count&&sources.length){const current=sources.findIndex(image=>image.src===main.src);count.textContent=`${(current<0?index:current)+1} / ${sources.length}`}window.clearTimeout(closeTimer);requestAnimationFrame(()=>{lightbox.dataset.state='open';closeButton?.focus()})}
  function close(){lightbox.dataset.state='closed';lightbox.setAttribute('aria-hidden','true');document.body.style.overflow=previousOverflow;window.clearTimeout(closeTimer);closeTimer=window.setTimeout(()=>{lightbox.hidden=true;returnFocus?.focus?.()},230)}
  let drag=null,suppressStageClick=false,suppressTimer=0;function resetDrag(viewport){viewport.classList.remove('is-dragging');drag=null}function attachSwipe(viewport,activateOnClick=false){viewport.addEventListener('pointerdown',event=>{if(event.button!==undefined&&event.button!==0)return;drag={id:event.pointerId,x:event.clientX,y:event.clientY,viewport,activateOnClick};viewport.classList.add('is-dragging');viewport.setPointerCapture?.(event.pointerId)});viewport.addEventListener('pointerup',event=>{if(!drag||drag.id!==event.pointerId)return;const gesture=drag,dx=event.clientX-gesture.x,dy=event.clientY-gesture.y;resetDrag(viewport);if(Math.abs(dx)<36||Math.abs(dx)<Math.abs(dy)*1.1)return;event.preventDefault();if(gesture.activateOnClick){suppressStageClick=true;window.clearTimeout(suppressTimer);suppressTimer=window.setTimeout(()=>{suppressStageClick=false},500)}select(index+(dx<0?1:-1))});viewport.addEventListener('pointercancel',()=>resetDrag(viewport));viewport.addEventListener('lostpointercapture',()=>{if(drag?.viewport===viewport)resetDrag(viewport)})}const mainViewport=gallery.querySelector('[data-gallery-image-viewport]'),lightboxViewport=lightbox.querySelector('[data-gallery-image-viewport]');if(mainViewport)attachSwipe(mainViewport,true);if(lightboxViewport)attachSwipe(lightboxViewport);stage.addEventListener('click',event=>{if(suppressStageClick){suppressStageClick=false;window.clearTimeout(suppressTimer);event.preventDefault();return}open()});thumbs.forEach((button,i)=>button.addEventListener('click',()=>select(i)));closeButton?.addEventListener('click',close);previous?.addEventListener('click',()=>select(index-1));next?.addEventListener('click',()=>select(index+1));lightbox.addEventListener('click',event=>{if(event.target===lightbox)close()});
  document.addEventListener('keydown',event=>{if(lightbox.hidden)return;if(event.key==='Escape'){event.preventDefault();close()}else if(event.key==='ArrowLeft'&&sources.length>1){event.preventDefault();select(index-1)}else if(event.key==='ArrowRight'&&sources.length>1){event.preventDefault();select(index+1)}});

  window.addEventListener('product:gallery-image',event=>{const {src,alt=''}=event.detail||{};if(!src)return;reflect(src,alt);if(!lightbox.hidden){swapImage(lightboxImage,src,alt);if(caption)caption.textContent=alt}});
  if(sources.length)select(0);
