</script>
<script>
(()=>{
  const form=document.querySelector('[data-cart-product]');if(!form)return;
  const price=document.querySelector('[data-product-price]'),priceWas=document.querySelector('[data-product-price-was]'),saleLabel=document.querySelector('[data-product-sale-label]'),variant=form.querySelector('[data-variant-selector]'),stock=form.querySelector('[data-stock-status]'),stockLabel=stock.querySelector('[data-stock-label]'),stockNote=stock.querySelector('[data-stock-note]'),submit=form.querySelector('button[type="submit"]'),money=new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'}),optionRadios=[...form.querySelectorAll('[data-variant-option]')],combinationSelect=form.querySelector('[data-variant-combinations]');
  function update(){
    let cents=Number(price.dataset.basePriceCents||0),regularCents=Number(price.dataset.baseRegularPriceCents||cents);
    const selectedVariant=variant?.tagName==='SELECT'?variant.selectedOptions[0]:(variant?.type==='radio'?form.querySelector('[data-variant-selector]:checked'):variant);
    const galleryImage=document.querySelector('[data-variant-image-gallery]');
    const stockQuantity=selectedVariant?.value?selectedVariant.dataset.quantity:stock.dataset.baseQuantity;const maxQuantity=stockQuantity===''||stockQuantity===undefined?999:Number(stockQuantity);quantity.max=String(Math.max(1,maxQuantity));if(Number(quantity.value)>maxQuantity)quantity.value=String(Math.max(1,maxQuantity));
    if(galleryImage){const imageSrc=selectedVariant?.dataset.imageSrc||galleryImage.dataset.defaultSrc;if(imageSrc){const imageAlt=selectedVariant?.dataset.imageSrc?(selectedVariant.textContent||'Изображение на избрания вариант').trim():galleryImage.dataset.defaultAlt||'';galleryImage.src=imageSrc;galleryImage.alt=imageAlt;window.dispatchEvent(new CustomEvent('product:gallery-image',{detail:{src:imageSrc,alt:imageAlt}}))}}
    if(selectedVariant&&selectedVariant.value){cents=Number(selectedVariant.dataset.priceCents||cents);regularCents=Number(selectedVariant.dataset.regularPriceCents||cents);const available=selectedVariant.dataset.available==='1';stockLabel.textContent=available?'В наличност':'Временно изчерпан';stockNote.hidden=!available;stock.classList.toggle('out',!available);submit.disabled=!available;}
    else if(variant){const state=variant.dataset.optionState;stockLabel.textContent=state==='partial'?'Изберете всички опции':state==='invalid'?'Тази комбинация не е налична':'Изберете продуктов вариант';stockNote.hidden=true;stock.classList.add('out');submit.disabled=true;}
    else submit.disabled=stock.dataset.baseAvailable!=='1';
    form.querySelectorAll('[data-price-field]').forEach(field=>{let amount=0;if(field.matches('select')){if(field.value)amount=Number(field.selectedOptions[0].dataset.priceCents||0);}else if(field.type==='radio'){if(field.checked)amount=Number(field.dataset.priceCents||0);}else if(field.type==='checkbox'){if(field.checked)amount=Number(field.dataset.priceCents||0);}else if(field.type==='file'){if(field.files&&field.files.length)amount=Number(field.dataset.priceCents||0);}else if(field.value.trim())amount=Number(field.dataset.priceCents||0);cents+=amount;regularCents+=amount;});
    price.textContent=money.format(cents/100);if(priceWas){priceWas.textContent=money.format(regularCents/100);priceWas.hidden=regularCents<=cents;}if(saleLabel)saleLabel.hidden=regularCents<=cents;syncQuantityControls();
  }
  function syncVariantCombination(){
    if(!variant||!combinationSelect)return;
    const dimensions=[...new Set(optionRadios.map(input=>input.dataset.variantOption))];
    const selected=Object.fromEntries(dimensions.map(dimension=>[dimension,form.querySelector(`[data-variant-option="${dimension}"]:checked`)?.value||'']));
    const selectedCount=Object.values(selected).filter(Boolean).length;
    variant.value='';variant.dataset.optionState=selectedCount===0?'':selectedCount<dimensions.length?'partial':'invalid';
    if(selectedCount===dimensions.length){
      const match=[...combinationSelect.options].find(option=>dimensions.every(dimension=>option.dataset[`option${dimension[0].toUpperCase()}${dimension.slice(1)}`]===selected[dimension]));
      if(match){variant.value=match.value;variant.dataset.optionState='';}
    }
    update();
  }
  const quantity=form.querySelector('[name="quantity"]'),quantityButtons=[...form.querySelectorAll('[data-quantity-step]')],feedback=form.querySelector('.product-cart-feedback');
  function syncQuantityControls(){const min=Number(quantity.min||1),max=Number(quantity.max||999),value=Number(quantity.value||min);quantityButtons.forEach(button=>{const delta=Number(button.dataset.quantityStep);button.disabled=delta<0?value<=min:value>=max;});}
  function stepQuantity(button){if(button.disabled)return false;const min=Number(quantity.min||1),max=Number(quantity.max||999),value=Number(quantity.value||min),step=Number(button.dataset.quantityStep||1),next=Math.max(min,Math.min(max,value+step));if(next===value){syncQuantityControls();return false;}quantity.value=String(next);quantity.dispatchEvent(new Event('input',{bubbles:true}));quantity.dispatchEvent(new Event('change',{bubbles:true}));return true;}
  let holdTimer=null,repeatTimer=null,holdButton=null,holdCount=0;
  function stopQuantityHold(){window.clearTimeout(holdTimer);window.clearTimeout(repeatTimer);holdTimer=null;repeatTimer=null;holdButton=null;holdCount=0;}
  function repeatQuantityStep(){if(!holdButton||!stepQuantity(holdButton)){stopQuantityHold();return;}holdCount++;repeatTimer=window.setTimeout(repeatQuantityStep,Math.max(45,125-Math.floor(holdCount/4)*15));}
  quantityButtons.forEach(button=>{button.addEventListener('pointerdown',event=>{if(button.disabled)return;event.preventDefault();stopQuantityHold();holdButton=button;stepQuantity(button);holdTimer=window.setTimeout(repeatQuantityStep,360);});button.addEventListener('pointerup',stopQuantityHold);button.addEventListener('pointercancel',stopQuantityHold);button.addEventListener('pointerleave',()=>{if(holdButton===button)stopQuantityHold();});button.addEventListener('click',event=>{if(event.detail===0)stepQuantity(button);});});
  window.addEventListener('pointerup',stopQuantityHold);window.addEventListener('blur',stopQuantityHold);
  quantity.addEventListener('input',syncQuantityControls);
  form.addEventListener('submit',async event=>{event.preventDefault();if(form.dataset.pending==='1'||submit.disabled)return;form.dataset.pending='1';submit.disabled=true;submit.classList.remove('is-success');submit.classList.add('is-loading');feedback.hidden=true;feedback.classList.remove('is-error');const label=submit.querySelector('.product-add-label'),originalLabel=label.textContent;try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-Token':form.querySelector('[name="_csrf"]').value}}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Продуктът не беше добавен.');const badge=document.querySelector('[data-cart-count]'),count=Number(payload.data.cart?.count||0);if(badge){badge.textContent=String(count);badge.closest('.cart-link')?.setAttribute('aria-label',`Количка, ${count} продукта`);badge.classList.remove('is-bumping');void badge.offsetWidth;badge.classList.add('is-bumping');}window.dispatchEvent(new CustomEvent('cart:updated',{detail:payload.data.cart}));window.setTimeout(()=>window.dispatchEvent(new CustomEvent('cart:open',{detail:payload.data.cart})),500);submit.classList.remove('is-loading');submit.classList.add('is-success');label.textContent='Добавено в количката';feedback.textContent=payload.data.message;feedback.hidden=false;window.setTimeout(()=>{submit.classList.remove('is-success');label.textContent=originalLabel;},1600);}catch(error){feedback.textContent=error instanceof Error?error.message:'Възникна грешка. Опитайте отново.';feedback.classList.add('is-error');feedback.hidden=false;}finally{submit.classList.remove('is-loading');delete form.dataset.pending;update();syncQuantityControls();}});
  form.addEventListener('input',()=>{update();syncQuantityControls();});
  form.addEventListener('change',event=>{if(event.target.matches('[data-variant-option]')){syncVariantCombination();return;}update();const input=event.target;if(input.matches('input[type=file][data-preview-target]')){const preview=document.getElementById(input.dataset.previewTarget);if(input.files&&input.files[0]){preview.src=URL.createObjectURL(input.files[0]);preview.style.display='block';}else{preview.removeAttribute('src');preview.style.display='none';}}});
  if(optionRadios.length)syncVariantCombination();else update();syncQuantityControls();
})();
</script>
